import{_ as t,l as r,o as e,c as s,v as n,p as l,x as i,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"Hong–Stein 信息扩散","description":"","frontmatter":{"title":"Hong–Stein 信息扩散","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/hong-stein-diffusion.md","filePath":"econ/hong-stein-diffusion.md","lastUpdated":1789023840000}'),h={name:"econ/hong-stein-diffusion.md"};function c(B,a,f,m,A,S){const o=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=n('<h1 id="hong–stein-信息扩散" tabindex="-1">Hong–Stein 信息扩散 <a class="header-anchor" href="#hong–stein-信息扩散" aria-label="Permalink to &quot;Hong–Stein 信息扩散&quot;">​</a></h1><div class="epigraph"><p>新息先在一部分人那里，再慢慢传到另一部分人；观察价格的动量交易者把扩散变成先不足、后过度。</p><footer>—— Hong and Stein, A Unified Theory of Underreaction, Momentum Trading, and Overreaction in Asset Markets, Journal of Finance, 1999</footer></div><p><a href="/econ/dhs-overconfidence">上一课</a>靠私人信号精度。本课缺口是传播：即使每个人都贝叶斯，信息若在人群中分段到达，价格也会先反应不足；简单动量规则再把不足推成过度。不重写自我归因。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Hong 与 Stein（1999）设两类有限理性：消息观察者只看自己那一段基本面新息，不从价格提取别人的信息；动量交易者只看过去价格，用简单正反馈外推。新息在消息观察者之间逐渐扩散，价格初期反应不足，动量为正。动量交易者吃这个正的序列相关，把价格推过基本面，长期反转。缺口是第三条统一不足–动量–过度的路：有限注意力式的分割，而不是 BSV 体制或 DHS 精度。</p><p><span class="marginnote">Hong、Lim 与 Stein 后来用分析师覆盖检验：覆盖少的股票动量更强，符合「扩散慢」。那是经验，本课只要机制。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>基本面新息分块，每块只被一群消息观察者看见。价格对未见块反应为零。动量交易者用滞后收益回归决定需求，寿命有限（又回到 DSSW 式的短视）。均衡路径：扩散期动量，过度期反转。比较静态：扩散越慢，动量窗口越长。</p>',8)),(e(),l(E,null,{default:i(()=>[p(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEWS%5B%22%E6%96%B0%E6%81%AF%E5%88%86%E6%AE%B5%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20UNDER%5B%22%E6%B6%88%E6%81%AF%E8%A7%82%E5%AF%9F%E8%80%85%E4%B8%8D%E8%AF%BB%E4%BB%B7%E6%A0%BC%3A%20%E5%8F%8D%E5%BA%94%E4%B8%8D%E8%B6%B3%22%5D%0A%20%20UNDER%20--%3E%20MOM%5B%22%E5%8A%A8%E9%87%8F%E4%BA%A4%E6%98%93%E8%80%85%E5%A4%96%E6%8E%A8%22%5D%0A%20%20MOM%20--%3E%20OVER%5B%22%E4%BB%B7%E6%A0%BC%E8%B6%8A%E8%BF%87%E5%9F%BA%E6%9C%AC%E9%9D%A2%2C%20%E5%8F%8D%E8%BD%AC%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是信息加总失败加正反馈。消息观察者的有限理性是：不从 \\(p\\) 反推别人的信号——这比「算错似然」更粗，接近<a href="/econ/bounded-rationality-satisficing">有限理性</a>的程序限制。动量交易者不看基本面，只看价格的时间序列启发式。两类单独都不会走完不足–过度的全路径，合在一起会。套利者若又短视又资本有限，挡不住中间那段动量。</p><p>与 <a href="/econ/emh">EMH</a>：半强式假定公开信息立刻进价格。「公开但尚未传到所有人」是对信息集的社会学放松，不是对 Fama 分层的改写。</p><p>消息观察者的程序限制是：不从 \\(p\\) 反演别人的块。若他们会读价格，扩散瞬间完成。动量交易者的程序是时间序列启发式，不看 \\(d\\)。有限寿命再次出现：他们吃中间的正相关，来不及为长期负相关负责——DSSW 式短视。分析师覆盖少则扩散慢，动量更强，是后文经验，本课只要这条比较静态。不写订单在簿上从一档传到另一档。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>若消息观察者能从价格充分提取，扩散瞬间完成，模型塌掉。动量交易者若会学习自己造成过度，正反馈减弱。本课不把所有动量写成 HS。也不写订单流在簿上的传播——那是微观结构。</p><p>后课默认：信念模型三件套（BSV/DHS/HS）之后，改评价函数的前景理论也可以定价，不必再错估 \\(p\\)。</p><p>新息分段到达，消息观察者不读价格，动量交易者只读价格：两类合在一起才走完不足–过度。</p><p>「公开但尚未传到所有人」放松的是信息集的到达，不是 Fama 分层本身。</p><p><span class="marginnote">动量交易者若学会自己造成过度，正反馈会减弱；本课不把所有动量写成 HS。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>信息分段扩散造成反应不足；动量交易者把它推成过度。</li><li>有限理性是程序：不读价格，或只读价格。</li><li>与 BSV/DHS 并列，不互相吞并。</li><li>扩散越慢，动量窗口越长。</li><li>若能从价格充分提取，模型塌掉。</li><li>出处：Hong and Stein, <em>JF</em> 1999。</li></ul>',12))])}const g=t(h,[["render",c]]);export{u as __pageData,g as default};
